568	// MemoShare is an access grant that permits read-only access to a memo via an opaque bearer token.
569	message MemoShare {
570	  option (google.api.resource) = {
571	    type: "memos.api.v1/MemoShare"
572	    pattern: "memos/{memo}/shares/{share}"
573	    singular: "share"
574	    plural: "shares"
575	  };
576	
577	  // The resource name of the share. Format: memos/{memo}/shares/{share}
578	  // The {share} segment is the opaque token used in the share URL.
579	  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
580	
581	  // Output only. When this share link was created.
582	  google.protobuf.Timestamp create_time = 2 [(google.api.field_behavior) = OUTPUT_ONLY];
583	
584	  // Optional. When set, the share link stops working after this time.
585	  // If unset, the link never expires.
586	  optional google.protobuf.Timestamp expire_time = 3 [(google.api.field_behavior) = OPTIONAL];
