22	// suppressSSEKey is a context key used to suppress the SSE broadcast from
23	// CreateMemo when it is called internally (e.g., from CreateMemoComment).
24	type suppressSSEKey struct{}
25	
26	const maxBatchGetLinkMetadata = 10
