465	func getConstValue(expr *exprv1.Expr) (interface{}, error) {
466		v, ok := expr.ExprKind.(*exprv1.Expr_ConstExpr)
467		if !ok {
468			return nil, errors.New("expression is not a literal")
469		}
470		switch x := v.ConstExpr.ConstantKind.(type) {
471		case *exprv1.Constant_StringValue:
472			return v.ConstExpr.GetStringValue(), nil
473		case *exprv1.Constant_Int64Value:
474			return v.ConstExpr.GetInt64Value(), nil
475		case *exprv1.Constant_Uint64Value:
476			return int64(v.ConstExpr.GetUint64Value()), nil
477		case *exprv1.Constant_DoubleValue:
